class Date:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    def display(self):
        """Instance method - works with instance data"""
        return f"{self.year}-{self.month:02d}-{self.day:02d}"

    @classmethod
    def from_string(cls, date_string):
        """Class method - creates instance from string"""
        year, month, day = map(int, date_string.split('-'))
        return cls(year, month, day)

    @classmethod
    def today(cls):
        """Class method - creates instance for today's date"""
        import datetime
        today = datetime.date.today()
        return cls(today.year, today.month, today.day)

    @staticmethod
    def is_valid_date(year, month, day):
        """Static method - validates date without needing instance or class"""
        if year < 1 or month < 1 or month > 12 or day < 1:
            return False

        # Simple validation - in real world, check actual days in month
        days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if month == 2 and year % 4 == 0:  # Leap year (simplified)
            days_in_month[1] = 29

        return day <= days_in_month[month - 1]

    @staticmethod
    def get_month_name(month):
        """Static method - returns month name"""
        months = [
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        ]
        return months[month - 1] if 1 <= month <= 12 else "Invalid"

# Usage
# Instance method
date1 = Date(2023, 12, 25)
print(date1.display())  # 2023-12-25

# Class method
date2 = Date.from_string("2023-06-15")
print(date2.display())  # 2023-06-15

date3 = Date.today()
print(date3.display())  # Current date

# Static method
print(Date.is_valid_date(2023, 12, 25))  # True
print(Date.is_valid_date(2023, 13, 1))   # False
print(Date.get_month_name(12))           # December
