class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        """String representation for printing"""
        return f"Vector({self.x}, {self.y})"

    def __repr__(self):
        """Detailed string representation for debugging"""
        return f"Vector(x={self.x}, y={self.y})"

    def __add__(self, other):
        """Addition operator"""
        if isinstance(other, Vector):
            return Vector(self.x + other.x, self.y + other.y)
        elif isinstance(other, (int, float)):
            return Vector(self.x + other, self.y + other)
        else:
            raise TypeError(f"Can't add Vector and {type(other).__name__}")

    def __sub__(self, other):
        """Subtraction operator"""
        if isinstance(other, Vector):
            return Vector(self.x - other.x, self.y - other.y)
        elif isinstance(other, (int, float)):
            return Vector(self.x - other, self.y - other)
        else:
            raise TypeError(f"Can't subtract {type(other).__name__} from Vector")

    def __mul__(self, other):
        """Multiplication operator (dot product for vectors, scalar multiplication for numbers)"""
        if isinstance(other, Vector):
            return self.x * other.x + self.y * other.y  # Dot product
        elif isinstance(other, (int, float)):
            return Vector(self.x * other, self.y * other)  # Scalar multiplication
        else:
            raise TypeError(f"Can't multiply Vector and {type(other).__name__}")

    def __eq__(self, other):
        """Equality comparison"""
        if isinstance(other, Vector):
            return self.x == other.x and self.y == other.y
        return False

    def __lt__(self, other):
        """Less than comparison (by magnitude)"""
        if isinstance(other, Vector):
            return self.magnitude() < other.magnitude()
        return NotImplemented

    def __len__(self):
        """Length (magnitude) of vector"""
        return int(self.magnitude())

    def __getitem__(self, index):
        """Indexing access"""
        if index == 0:
            return self.x
        elif index == 1:
            return self.y
        else:
            raise IndexError("Vector index out of range")

    def __setitem__(self, index, value):
        """Indexing assignment"""
        if index == 0:
            self.x = value
        elif index == 1:
            self.y = value
        else:
            raise IndexError("Vector index out of range")

    def __contains__(self, item):
        """Membership testing"""
        return item in (self.x, self.y)

    def magnitude(self):
        """Calculate vector magnitude"""
        import math
        return math.sqrt(self.x**2 + self.y**2)

# Usage
v1 = Vector(3, 4)
v2 = Vector(1, 2)

print(f"v1: {v1}")  # Uses __str__
print(f"v2: {v2}")

print(f"v1 + v2: {v1 + v2}")  # Uses __add__
print(f"v1 - v2: {v1 - v2}")  # Uses __sub__
print(f"v1 * v2: {v1 * v2}")  # Uses __mul__ (dot product)
print(f"v1 * 2: {v1 * 2}")    # Uses __mul__ (scalar multiplication)

print(f"v1 == v2: {v1 == v2}")  # Uses __eq__
print(f"v1 < v2: {v1 < v2}")    # Uses __lt__

print(f"Length of v1: {len(v1)}")  # Uses __len__
print(f"v1[0]: {v1[0]}")          # Uses __getitem__
print(f"5 in v1: {5 in v1}")       # Uses __contains__
