class ValidatedAttribute:
    """Descriptor for validated attributes"""

    def __init__(self, min_value=None, max_value=None, allowed_types=None):
        self.min_value = min_value
        self.max_value = max_value
        self.allowed_types = allowed_types
        self.name = None

    def __set_name__(self, owner, name):
        """Called when descriptor is assigned to a class"""
        self.name = name

    def __get__(self, instance, owner):
        """Get the attribute value"""
        if instance is None:
            return self
        return instance.__dict__.get(self.name)

    def __set__(self, instance, value):
        """Set the attribute value with validation"""
        # Type validation
        if self.allowed_types and not isinstance(value, self.allowed_types):
            raise TypeError(f"{self.name} must be one of {self.allowed_types}")

        # Range validation
        if self.min_value is not None and value < self.min_value:
            raise ValueError(f"{self.name} must be >= {self.min_value}")

        if self.max_value is not None and value > self.max_value:
            raise ValueError(f"{self.name} must be <= {self.max_value}")

        instance.__dict__[self.name] = value

    def __delete__(self, instance):
        """Delete the attribute"""
        if self.name in instance.__dict__:
            del instance.__dict__[self.name]

class Student:
    # Descriptors for validated attributes
    age = ValidatedAttribute(min_value=0, max_value=120, allowed_types=(int,))
    grade = ValidatedAttribute(min_value=0, max_value=100, allowed_types=(int, float))
    name = ValidatedAttribute(allowed_types=(str,))

    def __init__(self, name, age, grade):
        self.name = name
        self.age = age
        self.grade = grade

    def __str__(self):
        return f"Student(name='{self.name}', age={self.age}, grade={self.grade})"

# Usage
try:
    student1 = Student("Alice", 20, 85)
    print(student1)

    # This will raise an error
    student1.age = -5
except ValueError as e:
    print(f"Error: {e}")

try:
    # This will raise an error
    student1.grade = "A"
except TypeError as e:
    print(f"Error: {e}")
