class Singleton(type):
    """Metaclass that creates singleton classes"""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class Database(metaclass=Singleton):
    def __init__(self, connection_string):
        self.connection_string = connection_string
        self.connected = False

    def connect(self):
        if not self.connected:
            print(f"Connecting to {self.connection_string}")
            self.connected = True
        return self.connected

    def query(self, sql):
        if not self.connected:
            raise ConnectionError("Not connected to database")
        return f"Executed: {sql}"

# Usage
db1 = Database("mysql://localhost:3306/mydb")
db2 = Database("postgres://localhost:5432/mydb")

print(f"db1 is db2: {db1 is db2}")  # True - same instance
print(f"db1.connection_string: {db1.connection_string}")  # mysql://localhost:3306/mydb
print(f"db2.connection_string: {db2.connection_string}")  # mysql://localhost:3306/mydb

db1.connect()
db2.query("SELECT * FROM users")  # Works because db2 is the same instance
```

