class Product:
    def __init__(self, name, price, category):
        self.name = name
        self.price = price
        self.category = category

    def __str__(self):
        return f"{self.name} - ${self.price} ({self.category})"

class ProductFactory:
    """Factory class for creating different types of products"""

    @classmethod
    def create_electronics(cls, name, price):
        """Factory method for electronics"""
        return cls(name, price, "Electronics")

    @classmethod
    def create_clothing(cls, name, price):
        """Factory method for clothing"""
        return cls(name, price, "Clothing")

    @classmethod
    def create_book(cls, name, price):
        """Factory method for books"""
        return cls(name, price, "Books")

    @classmethod
    def create_from_dict(cls, data):
        """Factory method from dictionary"""
        return cls(data['name'], data['price'], data['category'])

    @classmethod
    def create_bulk_products(cls, product_list):
        """Factory method for creating multiple products"""
        return [cls.create_from_dict(product_data) for product_data in product_list]

# Usage
# Using factory methods
laptop = ProductFactory.create_electronics("Laptop", 999.99)
shirt = ProductFactory.create_clothing("T-Shirt", 25.00)
book = ProductFactory.create_book("Python Guide", 45.00)

print(laptop)   # Laptop - $999.99 (Electronics)
print(shirt)    # T-Shirt - $25.00 (Clothing)
print(book)     # Python Guide - $45.00 (Books)

# Creating from dictionary
product_data = {"name": "Mouse", "price": 50.00, "category": "Electronics"}
mouse = ProductFactory.create_from_dict(product_data)
print(mouse)    # Mouse - $50.00 (Electronics)

# Creating bulk products
bulk_data = [
    {"name": "Keyboard", "price": 75.00, "category": "Electronics"},
    {"name": "Jeans", "price": 60.00, "category": "Clothing"},
    {"name": "Notebook", "price": 15.00, "category": "Books"}
]

bulk_products = ProductFactory.create_bulk_products(bulk_data)
for product in bulk_products:
    print(product)
