class FileManager:
    def __init__(self, filename, mode='r'):
        self.filename = filename
        self.mode = mode
        self.file = None

    def __enter__(self):
        """Context manager entry"""
        self.file = open(self.filename, self.mode)
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit"""
        if self.file:
            self.file.close()

    def __str__(self):
        return f"FileManager({self.filename}, mode='{self.mode}')"

    def __repr__(self):
        return f"FileManager(filename='{self.filename}', mode='{self.mode}')"

class DataContainer:
    def __init__(self, data=None):
        self.data = data or []

    def __len__(self):
        return len(self.data)

    def __getitem__(self, index):
        return self.data[index]

    def __setitem__(self, index, value):
        self.data[index] = value

    def __delitem__(self, index):
        del self.data[index]

    def __iter__(self):
        return iter(self.data)

    def __contains__(self, item):
        return item in self.data

    def __add__(self, other):
        if isinstance(other, DataContainer):
            return DataContainer(self.data + other.data)
        elif isinstance(other, list):
            return DataContainer(self.data + other)
        else:
            raise TypeError(f"Can't add DataContainer and {type(other).__name__}")

    def append(self, item):
        self.data.append(item)

    def __str__(self):
        return str(self.data)

# Usage
# Context manager
with FileManager("test.txt", "w") as f:
    f.write("Hello, World!")

with FileManager("test.txt", "r") as f:
    content = f.read()
    print(f"File content: {content}")

# Data container
container1 = DataContainer([1, 2, 3])
container2 = DataContainer([4, 5, 6])

print(f"Length: {len(container1)}")           # 3
print(f"First item: {container1[0]}")         # 1
print(f"Contains 2: {2 in container1}")       # True
print(f"Combined: {container1 + container2}") # [1, 2, 3, 4, 5, 6]

# Iteration
for item in container1:
    print(item, end=" ")  # 1 2 3
print()
